import{_ as l,a as r}from"./chunks/e1b3924c2f88d6dab899.CzDXrQRY.js";import{_ as i,C as o,o as a,c as n,j as p,a as s,E as m,a6 as h}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"2023年赚取100万美元的最佳在线商业模式","description":"","frontmatter":{"title":"2023年赚取100万美元的最佳在线商业模式","originalTitle":"The Best Online Business Model To Make $1 Million In 2023","date":"2023-03-10","originalUrl":"https://thedankoe.com/letters/the-best-online-business-model-to-make-1-million-in-2023/","minutes":12,"sourceHash":"82b873db8795fced429846ac36f1c7b7d387097e8d7ef902390dc330c35d044c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-best-online-business-model-to-make-1-million-in-2023/"}]]},"headers":[],"relativePath":"letters/the-best-online-business-model-to-make-1-million-in-2023.md","filePath":"letters/the-best-online-business-model-to-make-1-million-in-2023.md"}'),f={name:"letters/the-best-online-business-model-to-make-1-million-in-2023.md"};function c(d,e,u,g,b,_){const t=o("ArticleMeta");return a(),n("div",null,[e[0]||(e[0]=p("h1",{id:"_2023年赚取100万美元的最佳在线商业模式",tabindex:"-1"},[s("2023年赚取100万美元的最佳在线商业模式 "),p("a",{class:"header-anchor",href:"#_2023年赚取100万美元的最佳在线商业模式","aria-label":'Permalink to "2023年赚取100万美元的最佳在线商业模式"'},"​")],-1)),m(t),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/ueeIJcjWZh8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>这很可能是自我提升领域最受欢迎的话题。</p><p>这类帖子总是很受欢迎：</p><ul><li>2023年最值得开始的副业</li><li>2023年最佳在线商业模式</li><li>如何在2023年变富并告别贫穷！！！！（请立即点击，否则你将倒霉10年！）</li></ul><p>我也对最后一个例子感到厌烦了。</p><p>所有这些视频、帖子和文章都缺少一个关键的方面：</p><p><em>在线业务的全局观。</em></p><p>它们只关注如何尽可能快地赚钱的技术技能、模式和拓客策略。</p><p>像往常一样，这并没有什么错。</p><p>我只是在这里描绘新的视角并开拓你的思维。</p><p>问题在于，<em>每个人</em>都想要快速的结果。</p><p><em>每个人</em>。</p><p>我曾经也是（现在依然是）。</p><p>我在这里要告诉你，这可能行不通，即使行得通，在接下来的3个月里它也不会长久存在，因为你是在和其他做起事来毫无目标的底层抢食者竞争。</p><p>因为他们处于一种求生状态，这种状态让他们甚至无法去考虑<a href="https://thedankoe.com/the-rise-of-the-value-creator-a-new-career-path/" target="_blank" rel="noreferrer">他们_一生的事业_。</a></p><p>就像现在短视频内容和代笔领域正在上演的内卷一样。</p><p>我收到过几百条私信和邮件，全是在推销同样的如同沃尔玛地摊货质量的短视频字幕（你们要做的就是去学一款真正的软件——而不是剪映——别再总想着走捷径了，兄弟们）。</p><p>人们不在乎变强，他们只在乎搞钱。</p><p>这是一个极其残酷的错误。</p><p>不过，我也经历了和其他人一样的阶段。</p><p>大多数人都会经历。</p><p>所以，请把这篇文章当作你商业之旅上的一颗觉知之种。</p><p>如果你正在用最新的策略追逐快钱，那你大概还有3-6个月的时间，之后你就必须转型、放弃，或者优先考虑成为最顶尖的人。</p><h2 id="什么是最佳商业模式" tabindex="-1">什么是最佳商业模式？ <a class="header-anchor" href="#什么是最佳商业模式" aria-label="Permalink to &quot;什么是最佳商业模式？&quot;">​</a></h2><p>最好的商业模式就是一个真正的商业模式。</p><p>不是副业。</p><p>不是免费的在线问卷调查。</p><p>不是把你每周的零花钱投资到加密货币里。</p><p>商业必须产生收入。你需要现金流。</p><p>不论算法和趋势如何变化，商业都具备扩张、转型以及在市场中定位自己的能力。</p><p>一半做短视频内容的人将会失业，因为他们不懂营销（我在这里说的不是表面知识，我说的是深厚的经验）。</p><p><strong>金钱是社会的命脉</strong></p><p>就像如果血液停止流动你的手就会坏死一样，你的业务也会如此，进而你的目标感也会随之枯竭。</p><p>目标感是超越你自身的东西。</p><p>如果你没有赚钱，这就意味着你没有用你所能提供的价值为社会做贡献。</p><p>商业是你赚钱的方式，因此也是你为社会做贡献的方式，所以它是你人生中一个合理的目标。</p><p>商业仅仅是你承载价值的容器，仅此而已。</p><p>在线问卷调查、照本宣科的商业模式（比如短视频代运营机构），以及绝大多数工作，都是没有灵魂的。</p><p><strong>商业拥有核心产品（Offer）与流量来源</strong></p><p>这是超越商业的普遍原则。</p><p>产品（Offer）= 价值</p><p>流量 = 人</p><p>你需要将有价值的产品或服务摆在一群想买的人面前。</p><p>就像在音乐节场外摆个热狗摊，而周围走过的全是喝醉的人。</p><p>或者，在约会中，把自己置于你理想伴侣所在的环境中，这样你才真正有机会约会成功。</p><p>如果你有产品（Offer）却没有流量，那你凭什么抱怨没有销量（或约会）？</p><p><strong>动态流量来源</strong></p><p>我不喜欢把你局限在一个框框里，而且我非常看好<a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">将创作者经济作为一种生活方式</a>。</p><p>无论你是否有意创业或成为一名创作者，这都是<em>新经济</em>。</p><p>因此，个人品牌是最接近“放之四海而皆准”的流量来源。</p><p>个人品牌就是<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">你如何成为细分领域</a>并消灭竞争的方式。</p><p>拥有了个人品牌：</p><ul><li>你不需要依赖广告</li><li>你可以谈论任何你想谈论的话题（<a href="https://thedankoe.com/dont-get-replaced-by-ai-how-to-write-authentic-content/" target="_blank" rel="noreferrer">前提是你要穿插一些与你的产品相关的内容</a>）</li><li>你不需要（长期）依赖冷拓客</li><li>你建立了一批受众，所以你可以做任何你想做的事</li><li>当你停止手动工作时，你的业务不会死掉</li><li>你不会被逼到一个特定的细分领域里，就像Zuby不仅仅谈论政治，他还做音乐、卖健身项目（大多数人只是无法摆脱需要获取客户的匮乏心态，所以他们的内容感觉很受限且无聊）。</li></ul><p>而且，你还能结识志同道合的人，周游世界，并真正享受你的工作。</p><p>我刚从一趟去见Joey Justice和Justin Scott的旅行中回来。我们之间的那种对话你在日常生活中是找不到的。</p><p><img src="'+l+'" alt=""></p><p>我不在乎是否能在这点上说服你，因为你最终都会得出这个结论。</p><p><strong>经验教训：</strong></p><p>个人品牌应该被视为你产品（Offer）的基础流量来源。</p><p>当人们知道你的名字时，付费广告的权威性就会增加。</p><p>向你的受众进行冷触达时，他们会更愿意和你交流（他们是真的会回复的）。</p><p>如果你明白内容的核心在于价值，而不是围绕特定主题写作，那你随时都可以转型。</p><p>换句话说，你是基于观点而不是主题来写内容，并从相关目标或问题的视角来阐述这些观点。主题只是帮助你生成观点的。</p><p>没人在乎主题，他们只在乎所有的这些东西将如何造福他们的生活。</p><h2 id="经验模型" tabindex="-1">经验模型 <a class="header-anchor" href="#经验模型" aria-label="Permalink to &quot;经验模型&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>过去我已经多次讨论过个人品牌策略，所以我就点到为止。</p><p>相反，我想把重点更多地放在产品（Offer）的创造上。</p><p>大多数人认为他们需要：</p><ul><li>完美的客户画像</li><li>完美的系统、课程或教练架构</li><li>拥有完善供应链管理的精美实体产品</li><li>先前的结果（而实际上你需要真正和某人合作才能取得结果）</li></ul><p>实际上，<em>你只需要比落后你一步的人<strong>懂</strong>得更多就行了。</em></p><p>看看“信息时代”和“注意力经济”这些词吧。知识就是王道。</p><p>这世界上的任何事物都会经历发展阶段。</p><p>无论是地球及其四季的更替、社会的进步，还是你在生活中达到一个新阶段，都不例外。</p><p>商业也不例外，如果你连起步都还没有，那你绝不可能在两周内就达到第10级并实现年入百万美元。</p><p>这是常识，但由于人类的本性、社交媒体的头条新闻以及集体追求速成的思维模式，大多数人都设定了这种不切实际的期望。</p><p>我们必须从小处着手。</p><h3 id="最小可行产品-minimum-viable-offer" tabindex="-1">最小可行产品（Minimum Viable Offer） <a class="header-anchor" href="#最小可行产品-minimum-viable-offer" aria-label="Permalink to &quot;最小可行产品（Minimum Viable Offer）&quot;">​</a></h3><p>我之前在<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">一人企业商业模式（The One Person Business Model）的信件</a>中简要地提到过这一点，但现在我想给你们讲讲具体的细节。</p><p>最小可行产品围绕着一个<em><strong>单一的</strong></em>技能或兴趣展开。</p><p>收取高昂的费用需要时间、经验，以及在真实世界中建设时跨学科技能的获取（而不是光看关于如何与客户合作的理论文章）。</p><p>有了你的单项技能或兴趣后，你就可以立即将其转化为相关的自由职业、教练、咨询或辅导产品（Offer）。</p><p>当我说“技能”时，我指的是类似以下这些：</p><ul><li>邮件营销</li><li>网页设计</li><li>文案写作</li><li>Facebook广告</li><li>品牌设计</li><li>以及来自<a href="https://thedankoe.com/the-1-million-dollar-skill-stack-learn-in-this-order/" target="_blank" rel="noreferrer">100万美元技能栈</a>中的任何其他技能</li></ul><p>当我说“兴趣”时，我指的是类似以下这些：</p><ul><li>健康与健身</li><li>表现与生产力</li><li>个人成长与灵性</li><li>人际关系或约会</li></ul><p>诚然，那些也是技能，但我想在这里做一个区分，以帮助构建我们正在讨论的框架。</p><p><strong>快速包装你的产品（Offer）</strong></p><p>如果是技能，那应该非常显而易见。</p><p>你可以卖网页设计、落地页设计、邮件营销、销售页文案，或者品牌设计服务（比如主页横幅、头像和电子书封面设计）。</p><p>从本质上讲，你可以去上一门初级课程，看一些YouTube视频，然后就开始销售（记住，你现在不是想去收天价的费用……<em>你必须打磨你的产品，而你无法去打磨一个根本不存在的东西</em>）。</p><p>任何人都可以快速掌握这些技能中的一种，并开始通过你的个人品牌获取客户。</p><p>我过去写过很多关于这个话题的信件，但在<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a>里有超过10门课程和180多种策略能帮你做到这一点。或者你可以参加<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>大师课，用我个人的系统将你自己产品化。</p><p><strong>对于教练、咨询或辅导产品（Offer）</strong></p><p>首先，要理解这个普遍原则：</p><ul><li>目标（你的客户想达到的状态）</li><li>路径（你带领他们达到该状态的独特方式）</li><li>问题（他们现在正在挣扎的痛点）</li></ul><p>简而言之，营销就是这么回事。</p><p>你在推销的是一种<em>转变</em>，这种转变要么是你自己已经实现的，要么是你帮助别人实现过的，要么是你正想开始帮助别人去实现的。</p><p><strong>记住</strong>：<em>自由职业者是通过先跟客户合作来积累经验的。他们大多没有自己的业务来先做个示范。他们只是学习这项技能，然后开始将其卖给理想的客户。你不需要有先前的结果才能开始……因为结果是在你帮助自己<strong>或者</strong>帮助他人的过程中产生的。</em></p><p>教练和咨询类产品非常显而易见，你帮助他们解决某个兴趣领域的难题，比如健身、生产力，或是他们生活中的其他事情。</p><p>对于辅导类产品，你将是<em><strong>教</strong></em>他们这项技能，而不是替他们去做。就把它当成是你在一对一地带着他们学完一门课程。</p><ul><li>教他们如何写电子邮件时事通讯</li><li>教他们如何剪辑YouTube视频</li><li>教他们如何写社交媒体内容</li><li>教他们网页设计或平面设计</li></ul><p>这是除了做自由职业之外的另一个选项。你教他们怎么做，而不是替他们做。</p><p>这对针对新手受众来说效果出奇地好。更多的人应该去打造一款辅导类产品（如果你处于初级或中级水平，我会建议你做一款辅导类产品，跳过自由职业带来的痛苦……这也有助于你在内容创作中向新手写任何你想写的主题）。</p><p>而且你所获得的结果能够更容易地转化为数字产品/课程。</p><p>作为初学者，你之所以这样做，而不是直接做一门课程，是因为：</p><ul><li>你可以收费更高（并在服务了几个客户后提价至2500美元以上）</li><li>你还没有受众（流量）来带来持续的课程销量</li><li>你还不知道什么方法能产生结果（哪怕你以为你知道，其实你并不知道），这就是为什么你要做一对一服务并在过程中不断优化</li><li>你可以使用直接触达的方法或<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">不同的策略</a>来获取客户</li></ul><p>简而言之，完成一笔1000美元的销售比完成十笔100美元的销售要“容易”得多。</p><p>你开始意识到你可以完全掌控自己的收入。</p><p>这让人感觉十分自由。</p><p>教练、咨询或辅导服务通常包含以下几个要素：</p><p><strong>1) 你要教授或帮助他们的内容结构。</strong></p><p>想想他们现在所处的阶段（A点）以及你要帮助他们达成的目标（B点）。</p><p>现在，为他们需要学习和执行的必要事项创建一个初步大纲。</p><p>这不必变成一份教学大纲，因为你会在通话中带他们过一遍所有内容。</p><p>大多数教练、顾问等销售的项目，都是直接从他们的课程或书籍中提取的教学内容。</p><p>是的，完全一样的东西，因为那就是他们取得成果的方法。区别在于一对一的帮助和监督机制。</p><p><strong>如果你想很好地构建你的教学结构：</strong></p><ul><li>定义A点是什么（他们现在的状态以及正在经历的问题）</li><li>定义B点是什么（你能帮助他们达到的人生理想状态）</li><li>到达那里的路径——列出书的章节或课程的模块——你可以从别人的书或课程中寻找灵感，以确保你没有遗漏任何东西。</li><li>根据你的判断来填充内容。如果你愿意，你可以结合多种兴趣……你不必将其局限于某一个特定兴趣，变得和其他人一样。想想一本书是如何综合多种教学内容来达到一个结果的。</li></ul><p><strong>2) 每周通话，回答问题并教授他们需要掌握的知识。</strong></p><p>我建议销售包含4次通话的套餐。每周一次。</p><p>你将准确地教授他们需要了解的内容，并回答他们提出的任何问题。</p><p>从4次通话开始，因为这能让你在起步阶段收取更高的费用。</p><p>而且，你可能无法在一次通话中就让他们达到理想的最终结果（B点）。</p><p>4次通话能让你创造出比仅仅说“我会和你打个咨询电话，帮你想办法解决你遇到的任何难题”更具吸引力的报价。</p><p>你在营销一种蜕变。</p><p><strong>3) 每周行动清单和文字沟通权限</strong></p><p>在每次通话结束后，你应该确切地告诉他们该做什么。</p><p>你可以创建工作表、任务或项目让他们完成。</p><p>如果你卖的是健康教练服务，让他们追踪自己的饮食并每天早上称体重。</p><p>如果你卖的是设计辅导服务，让他们制作出社交媒体设计的第一版迭代。</p><p>你应该有一种在通话之外与他们沟通的方式，比如通过Telegram、Whatsapp，或者直接用手机发短信。</p><p><strong>初期收费500至1000美元</strong></p><p>对于单项技能的自由职业服务，或者是包含4次通话的套餐（教练、咨询或辅导），起步价定为500美元，在服务了最初的几个客户后提价至1000美元，并在你经历这个课程的过程中以此为基础不断完善你的报价。</p><p>更棒的是，我建议你免费帮助别人。</p><p>如果你是一名创作者，并且正在<a href="https://thedankoe.com/how-to-network-with-millionaires-and-build-a-name-for-yourself/" target="_blank" rel="noreferrer">与其他创作者建立人脉网络</a>，可以为他们提供几次免费通话。</p><p>随着你们双方的成长，他们的评价会不断升值。</p><p>当我有100万粉丝时，我在500粉丝时写下的一份评价，其价值将高达数万美元。人们仅仅因为看到我的名字与该产品联系在一起就会去购买。</p><p><em>来自创作者的评价是增值资产。</em></p><p>不要因为缺钱就只想着钓大鱼。</p><p>稳扎稳打。</p><p><strong>你可以扩大你的客户业务，或者实现产品化</strong></p><p>随着你发展自己的品牌，为客户带来成果，并通过获取技能（永不停止学习）来完善你的报价……你有两个选择。</p><ol><li>创造更具吸引力的报价并提高价格。</li><li>将你的教学内容变成同期群课程（cohort-based course），并用你的受众来为其提供动力（仅适用于教练、咨询或辅导服务）。</li></ol><p>我当然推荐第二个选择。</p><p>它能给你更多的空闲时间、更少的压力和更大的杠杆。</p><p>杠杆，杠杆，还是杠杆。</p><p>主要的缺点是你需要持续扩大受众来为同期群课程注入活水。这很困难，但绝对值得，总比陷入“要么撑死要么饿死”的自由职业循环要好得多。</p><p>随后，一旦你的同期群课程取得了成果和客户评价，你就可以进一步将其产品化，变成一门按需自学的课程。</p><p>现在，你无需再做任何工作，可以把空闲时间花在打造更高投资回报率（ROI）的项目上。</p><p>正如我们在上一封信中所讨论的，你为你下方的市场降低了饱和度。</p><p>创作者经济是不可能饱和的。</p><p><strong>扩大规模至一百万</strong></p><p>在以下情况下，赚到100万美元将成为必然：</p><ul><li>你不因守着一份报酬过低的报价而停滞不前</li><li>你继续增加你的粉丝量（是的，这是可能的，不要停滞不前然后把你对社交媒体的无知怪罪于算法）</li><li>你不断进化，你的报价也不断进化，你在增加收入的同时减少了花在工作上的时间</li></ul><p>我实现这一目标的路径是通过个人品牌、数字产品以及无休止的迭代。</p><p>我花了3年时间（带着一些过往的经验）。</p><p>希望我的内容能帮你更快到达那里。</p><p>—— 丹</p><hr><p><a href="/en/letters/the-best-online-business-model-to-make-1-million-in-2023">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',161))])}const M=i(f,[["render",c]]);export{T as __pageData,M as default};
